local ONE = require 'ejoysdk_lua.vendors.one_ios'
local DS_PC = require 'ejoysdk_lua.vendors.ds_pc'
local E = require "ejoysdk_lua.ejoysdk"
local EM = require "ejoysdk_lua.ejoysdk_module"

local TAG = EM.MODULE.VENDORS.DS_LOGIN_PROXY

local lingxiName = "ALIGAMES"
local oneName = "ONE"
local airlineV2Name = 'AIRLINE_V2'

local M = {}

local auth_listener = nil
function M.set_auth_listener(cb)
    if tostring(type(cb)) ~= 'function' then
        return
    end

    auth_listener = cb

    if _ejoysdk.os() == "ios" then
        ONE.set_auth_listener(auth_listener) -- 同步设置one里的回调
    elseif _ejoysdk.os() == "windows" then
        DS_PC.set_auth_listener(auth_listener)
    end

end

local function check_if_support_login(vendor_name)
    if not vendor_name then
        return false
    end

    local UNI = require "ejoysdk_lua.vendors.unisdk"
    local sdk_infos = UNI.get_sdk_infos()
    for sdk_name, _sdk_info in pairs(sdk_infos) do
        if sdk_name == vendor_name then
            return true
        end
    end

    return false
end

function M.check_if_support_lingxi_login()
    return check_if_support_login(lingxiName)
end

function M.check_if_support_lingxi_login_v2()
    return check_if_support_login(airlineV2Name)
end


function M.check_if_support_dingding_login()
    local result = false
    local UNI = require "ejoysdk_lua.vendors.unisdk"
    local sdk_infos = UNI.get_sdk_infos()
    local one_data = sdk_infos[oneName]
    if one_data and one_data['meta_data'] then
        local meta_data = one_data['meta_data']
        if meta_data['login_cover_lingxi'] == true then
            E.LOG.debug(TAG, 'ONE登录配置为覆盖灵犀登录，为了兼容star旧包和新游戏的ONE登录。')
            result = true
        end
    end

    return result
end



--大圣登录协议，首次登录和自动登录都用这个接口
local function login_ds_with_params(params, cb)
    local DSP = require "ejoysdk_lua.protocal.ejoysdk_ds_protocal"

    DSP.post(DSP.SERVICE.ACCOUNT_LOGIN, params, function(succ, ...)
        if succ then
            local data = ...
            if data and data.ex then
                local exStr = data.ex
                local JSON = require "ejoysdk_lua.ejoysdk_json"
                local exJson = JSON.safe_decode(exStr)
                if exJson then
                    data.ex = exJson
                end
            end

            if cb then
                cb(true, data)
            end

        else
            local code, msg = ...
            E.LOG.warn(TAG, 'request one account failed, code:' .. tostring(code) .. ', msg:' .. tostring(msg))
            if cb then
                local resp = {
                    code = code,
                    message = msg,
                    msg = msg
                }
                cb(false, resp)
            end
        end
    end)

end

function M.login_to_ds_service(params, cb)
    login_ds_with_params(params, cb)
end

function M.login()

    -- 设置函数回调
    if _ejoysdk.os() == "ios" then
        ONE.set_ds_login_function(function(params, cb)
            login_ds_with_params(params, cb)
        end)

        ONE.login() -- check_token也可以
    elseif _ejoysdk.os() == "windows" then
        DS_PC.set_ds_login_function(function(params, cb)
            login_ds_with_params(params, cb)
        end)

        DS_PC.login() -- check_token也可以
    end

end

function M.logout()
    if _ejoysdk.os() == "ios" then
        ONE.logout()
    elseif _ejoysdk.os() == "windows" then
        DS_PC.logout()
    end

end

return M
